import{_ as a,o as e,c as t,a2 as s}from"./chunks/framework.1C62pOns.js";const h=JSON.parse('{"title":"Integrações","description":"","frontmatter":{},"headers":[],"relativePath":"pt/interface/integracoes.md","filePath":"pt/interface/integracoes.md","lastUpdated":1791311821000}'),r={name:"pt/interface/integracoes.md"};function n(d,o,i,p,c,l){return e(),t("div",null,[...o[0]||(o[0]=[s(`<h1 id="integracoes" tabindex="-1">Integrações <a class="header-anchor" href="#integracoes" aria-label="Permalink to &quot;Integrações&quot;">​</a></h1><p>Levam um agente ou time para onde as pessoas já conversam — WhatsApp, Teams, Telegram, e-mail — em vez de pedir que elas entrem na plataforma.</p><p>Desde a versão 1.0.26.7 a plataforma não fala mais com cada canal por conta própria: as integrações de WhatsApp (Evolution API) e de Microsoft Teams foram retiradas. Quem fala com o canal é o <strong>N8N</strong>, que já tem um nó pronto para cada um deles. A plataforma cuida do que é dela: o agente, o time, o workflow.</p><h2 id="do-canal-para-a-plataforma" tabindex="-1">Do canal para a plataforma <a class="header-anchor" href="#do-canal-para-a-plataforma" aria-label="Permalink to &quot;Do canal para a plataforma&quot;">​</a></h2><p>O caminho é sempre o mesmo:</p><ol><li>um fluxo do N8N recebe a mensagem do canal (o gatilho do WhatsApp, do Teams…);</li><li>um nó <strong>HTTP Request</strong> chama o workflow da plataforma que conversa com o agente;</li><li>a resposta do workflow volta ao canal pelo nó de envio do próprio N8N.</li></ol><p>A chamada é o disparo de workflow por API:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>POST /api/workflow/&lt;id&gt;/run</span></span>
<span class="line"><span>Authorization: Basic &lt;token de API dos workflows&gt;</span></span>
<span class="line"><span>X-Impersonate-User: &lt;usuário da plataforma&gt;   (opcional)</span></span>
<span class="line"><span>Content-Type: application/json</span></span>
<span class="line"><span></span></span>
<span class="line"><span>{ &quot;mensagem&quot;: &quot;texto recebido&quot;, &quot;remetente&quot;: &quot;...&quot; }</span></span></code></pre></div><p>O corpo vira o contexto da execução, e a resposta traz o resultado do workflow na hora — não é preciso consultar depois. O token é o da tela de <a href="/pro-agent-hub-installer/pt/interface/administracao">Administração</a>, e o <code>X-Impersonate-User</code> decide em nome de quem o workflow roda: sem ele, roda como o usuário de serviço.</p><div class="tip custom-block"><p class="custom-block-title">Quem escreveu a mensagem</p><p>O que vem do canal — nome, número, e-mail — é escrito por quem mandou a mensagem. Passe esses campos ao agente como dado, nunca como instrução, e não os use para decidir permissão.</p></div><h2 id="da-plataforma-para-o-n8n" tabindex="-1">Da plataforma para o N8N <a class="header-anchor" href="#da-plataforma-para-o-n8n" aria-label="Permalink to &quot;Da plataforma para o N8N&quot;">​</a></h2><blockquote><p>Cadastro em <strong>Configurações → aba N8N</strong>, restrito a master.</p></blockquote><p>Uma integração N8N guarda o <strong>endereço da instância</strong> (ex.: <code>https://n8n.empresa.com</code>, ou <code>https://empresa.com/n8n</code> se o N8N roda num subcaminho; nunca com <code>/webhook/</code>), a <strong>autenticação</strong> do webhook e o <strong>prazo</strong> padrão das chamadas.</p><p><strong>Autenticação.</strong> O nó Webhook do N8N oferece <em>Header Auth</em>, <em>Basic Auth</em>, <em>JWT Auth</em> ou nenhuma. Todas cabem no par cabeçalho/valor do cadastro:</p><table tabindex="0"><thead><tr><th>No nó Webhook</th><th>Cabeçalho</th><th>Valor</th></tr></thead><tbody><tr><td>Header Auth</td><td>o <em>Name</em> da credencial</td><td>o <em>Value</em> da credencial</td></tr><tr><td>Basic Auth</td><td><code>Authorization</code></td><td><code>Basic </code> + base64 de <code>usuário:senha</code></td></tr><tr><td>JWT Auth</td><td><code>Authorization</code></td><td><code>Bearer </code> + o token</td></tr></tbody></table><p>O segredo nunca volta à tela: ao editar, deixe o campo em branco para manter o atual, ou marque <em>Remover o segredo atual</em>. Ele também não fica no workflow — o fluxo guarda só o número da integração e o caminho do webhook, e é por isso que quem monta o workflow não consegue mandar a chamada para outro lugar.</p><p>Em <strong>Avançado</strong> ficam os prefixos <code>webhook</code> e <code>webhook-test</code>. Só mude se a instância do N8N os trocou pelas variáveis <code>N8N_ENDPOINT_WEBHOOK</code> e <code>N8N_ENDPOINT_WEBHOOK_TEST</code>.</p><p>No workflow high-code (ou num nó Script), a chamada é:</p><div class="language-python vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">resposta </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> call_n8n(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;pedido-aprovado&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, {</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;pedido&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">123</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;cliente&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;ACME&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">})</span></span></code></pre></div><ul><li>o primeiro argumento é o número da integração (aparece na lista da aba);</li><li>o segundo é o <em>Path</em> do nó Webhook; com parâmetros de caminho, informe os valores (o Path <code>pedido/:id</code> vira <code>&quot;pedido/123&quot;</code>);</li><li>o terceiro são os dados: vão como JSON no corpo (no N8N, <code>$json.body</code>); em <code>GET</code> e <code>HEAD</code>, viram parâmetros da URL (<code>$json.query</code>). O N8N limita o corpo a 16 MB.</li></ul><p>O método é o <em>HTTP Method</em> do nó (<code>method=&quot;GET&quot;</code>, por exemplo; o padrão é <code>POST</code>). A resposta depende do <em>Respond</em> do nó Webhook:</p><table tabindex="0"><thead><tr><th>Respond</th><th>O que <code>call_n8n</code> devolve</th></tr></thead><tbody><tr><td>Immediately</td><td>a mensagem de que o fluxo começou — ele segue sozinho</td></tr><tr><td>When Last Node Finishes</td><td>a saída do último nó</td></tr><tr><td>Using &#39;Respond to Webhook&#39; Node</td><td>o que aquele nó definir</td></tr></tbody></table><p>JSON vira dicionário, texto vira texto e arquivo (um PDF, por exemplo) vira bytes. A URL de <strong>produção</strong> só existe com o fluxo publicado no N8N; a de <strong>teste</strong> (<code>test_mode=True</code>) só responde enquanto o editor está em <em>Listen for test event</em>, por 120 segundos. Webhook não registrado responde 404, e a mensagem de erro diz isso. No N8N Cloud, um fluxo que não responde em 100 segundos falha.</p><p>Uma falha — integração desabilitada, rede, resposta de erro do N8N — levanta <code>N8nCallError</code>, com <code>status</code> e <code>body</code> quando o N8N respondeu. A referência completa está em <a href="/pro-agent-hub-installer/pt/funcoes/workflow_highcode">Funções</a>.</p><h3 id="no-workflow-low-code" tabindex="-1">No workflow low-code <a class="header-anchor" href="#no-workflow-low-code" aria-label="Permalink to &quot;No workflow low-code&quot;">​</a></h3><p>O nó <strong>N8N</strong> (grupo <em>Integrações</em> da paleta) faz a mesma chamada sem código: escolha a integração, informe o caminho do webhook (aceita <code>{{variavel}}</code>, como em <code>pedido/{{pedido_id}}</code>), o método e os dados — uma variável, uma referência <code>{{no.campo}}</code> ou um JSON com variáveis. A resposta vai para a variável de saída (<code>n8n_result</code>). O nó tem duas saídas, <strong>OK</strong> e <strong>ERRO</strong>, como o nó Planejador: a falha desvia por ERRO quando ela está ligada, e o motivo fica em <code>{{nome_do_no.n8nError}}</code>. <em>Quando falhar</em> escolhe entre continuar, parar o caminho ou falhar o workflow.</p><p>Ao exportar as configurações, as integrações N8N vão junto, com o segredo cifrado como as demais senhas.</p>`,27)])])}const u=a(r,[["render",n]]);export{h as __pageData,u as default};
